import random

class Combattant:
    def __init__(self, nom, pv, force):
        self.nom = nom
        self.pv = pv
        self.force = force

    def subir_degats(self, d):
        self.pv = max(0, self.pv - d)
        print(f"{self.nom} perd {d} PV ({self.pv} restants)")

    def est_vivant(self):
        return self.pv > 0

    def attaquer(self, cible):
        cible.subir_degats(random.randint(self.force - 3, self.force + 3))


class Guerrier(Combattant):
    def __init__(self, nom):
        super().__init__(nom, 120, 12)

    def attaque_speciale(self, cible):
        print(f"{self.nom} frappe de toutes ses forces !")
        cible.subir_degats(random.randint(18, 26))


class Mage(Combattant):
    def __init__(self, nom):
        super().__init__(nom, 80, 8)
        self.mana = 30

    def attaque_speciale(self, cible):
        if self.mana >= 10:
            self.mana -= 10
            print(f"{self.nom} lance une boule de feu !")
            cible.subir_degats(30)
        else:
            print("Plus assez de mana !")


def combat():
    choix = input("Guerrier ou Mage ? ").lower()
    joueur = Mage("Toi") if choix == "mage" else Guerrier("Toi")
    ennemi = Combattant("Orc", 90, 10)
    potions = 2
    while joueur.est_vivant() and ennemi.est_vivant():
        action = input("1. Attaque  2. Spéciale  3. Potion > ")
        if action == "2":
            joueur.attaque_speciale(ennemi)
        elif action == "3" and potions > 0:
            potions -= 1
            joueur.pv += 30
            print(f"Tu bois une potion : {joueur.pv} PV")
        else:
            joueur.attaquer(ennemi)
        if ennemi.est_vivant():
            ennemi.attaquer(joueur)
    print("Victoire !" if joueur.est_vivant() else "Défaite...")

if __name__ == "__main__":
    combat()

