def afficher_mot(mot, trouvees):
    return " ".join(l if l in trouvees else "_" for l in mot)


def est_complet(mot, trouvees):
    return all(l in trouvees for l in mot)


def main():
    mot = "python"
    trouvees = []
    vies = 7
    while vies > 0:
        print(afficher_mot(mot, trouvees))
        if est_complet(mot, trouvees):
            print("Gagné !")
            return
        lettre = input("Lettre ? ")
        if lettre in mot:
            trouvees.append(lettre)
        else:
            vies -= 1
    print("Perdu !")


if __name__ == "__main__":
    main()

